withCtx({}, (ctx) => {
  writeFileSync(join(ctx.work, 'skills', 'foo', '.env'), `TOKEN=${SECRET}\n`);
  const res = run(ctx);
  assertBlocked(res, 'skills/foo/.env');
  assert.ok(res.stderr.includes('!!'));
  assert.ok(!res.stderr.includes(SECRET));
  assert.ok(!res.stdout.includes(SECRET));

